from fractions import Fraction


def zero_profit_half_spread(alpha, outcomes):
    """Smallest half-width h >= 0 around the mean of the
    equally likely outcomes with (1 - alpha) * h >= alpha * L(h),
    where L(h) is the average loss to a fully informed trader.
    Return an exact Fraction."""
    alpha = Fraction(alpha)
    xs = [Fraction(x) for x in outcomes]
    m = sum(xs) / len(xs)

    def gap(h):
        loss = sum(max(abs(x - m) - h, 0) for x in xs) / len(xs)
        return (1 - alpha) * h - alpha * loss

    points = sorted(set([Fraction(0)] + [abs(x - m) for x in xs]))
    if gap(points[0]) >= 0:
        return points[0]
    for lo, hi in zip(points, points[1:]):
        if gap(hi) >= 0:
            return lo + (hi - lo) * (-gap(lo)) / (gap(hi) - gap(lo))
    return points[-1]
